import json,pathlib,datetime,hashlib
from PIL import Image
base=pathlib.Path('/workspace/seven-png-campaign');q=base/'qualification-client';context=json.loads((q/'context.json').read_text());profile=json.loads((q/'profile.json').read_text());rows=[json.loads(l) for l in (q/'rows.jsonl').open() if json.loads(l)['phase']=='qualification'];old=json.load(open('/workspace/png-calibration-v4/measurement/review.json'))
checks={};verified=0
bm_fail={'flowchart.md:903':'No branch is parsed into a malformed node; End/No source facts not retained.','flowchart.md:919':'End label is malformed as E[End; source label not retained.','flowchart.md:970':'Group three and required nodes/edges are missing or malformed.','flowchart.md:998':'Required group membership/nodes/edges are missing or malformed.','classDiagram.md:311':'Composition and aggregation diamonds are not painted.','entityRelationshipDiagram.md:213':'PERSON and its non-identifying relationship are omitted.','mindmap.md:46':'Public API reports unsupported mindmap syntax.','flowchart.md:1065':'Collapsed group exposes internal A/B/C.'}
for c in profile['cases']:
 own={};pixels={}
 for p in context['participants']:
  k=p['id'];r=next(r for r in rows if r['participant']==k and r['case']==c['id']);suffix=c['id'].split('/')[-1]
  if r.get('png'):
   image=Image.open(q/r['png']).convert('RGBA');decoded=hashlib.sha256(image.tobytes()).hexdigest();assert image.size==(1200,900) and decoded==r['inspection']['pixelSha256'];pixels[k]=decoded;verified+=1
  if k in ['mermaid','agentic','pele','flutter']:
   prior=old['cases'][c['id']];assert pixels[k]==prior['pixels'][k];own[k]=dict(prior['checks'][k]);own[k]['evidence']='Exact decoded-pixel match to earlier reviewed output; source facts rechecked where clarified.'
  else:
   reason=bm_fail.get(suffix) if k=='beautiful' else ('Public API reports unsupported mindmap syntax.' if suffix=='mindmap.md:46' and k=='zombie' else 'Collapsed group exposes internal A/B/C.' if suffix=='flowchart.md:1065' else None)
   own[k]={'pass':reason is None and r['status']=='ok','reason':reason or 'Source labels, relationships, shape meanings and legibility reviewed in actual painted output.','evidence':f"{q.name}/{r.get('png','rows.jsonl')}"}
  if suffix=='stateDiagram.md:26':own[k]['clarification']='Two transitions to termination are required. Mermaid oracle, Dart and Flutter share one final marker; duplicated final markers are also accepted.'
  if suffix=='sequenceDiagram.md:101' and k in ['beautiful','zombie']:own[k]['clarification']='Outlined person icons express actor roles and are accepted as a visual style; messages/directions retained.'
 eligible=c['role']=='candidate' and all(x['pass'] for x in own.values())
 checks[c['id']]={'eligible':eligible,'checks':own,'pixels':pixels,'role':c['role']}
review={'reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'Main: 61 new painted BM/ZM/native-Dart outputs plus two unsupported inputs in unscaled contact crops; 84 prior reviewed outputs reused only after exact RGBA match. PIL independently decoded all 145 returned qualification PNGs.','renderIdentity':context['renderIdentity'],'participants':[p['id'] for p in context['participants']],'manifestSha256':hashlib.sha256((q/'profile.json').read_bytes()).hexdigest(),'clarifications':['Correct state26 historical expectation: two terminal transitions, not two distinct final markers. Actual pinned Mermaid oracle shares a final marker. No source changes.','Person-shaped actor icons and stick figures both express actor role; boxes remain participants. Other relationship shape meanings such as composition/aggregation diamonds remain required.'],'cases':checks,'independentPngsVerified':verified}
(base/'review.json').write_text(json.dumps(review,indent=2)+'\n')
print('eligible',sum(c['eligible'] for c in checks.values()),'PIL PNGs',verified)
for p in review['participants']:print(p,sum(c['checks'][p]['pass'] for c in checks.values() if c['role']=='candidate'),'/20 candidates')
plan={'declaredAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'protocol':context['protocol'],'producerCommit':context['baseCommit'],'renderIdentity':context['renderIdentity'],'reviewSha256':hashlib.sha256((base/'review.json').read_bytes()).hexdigest(),'profileCandidatesBeforeTiming':20,'eligibleBeforeTiming':[c for c,v in checks.items() if v['eligible']],'fullCoverageInputs':548,'independentLaunchBlocksPerParticipant':20,'warmupPassesPerLaunch':2,'measuredCallsPerCasePerLaunch':3,'score':'Geometric mean across launch blocks and common inputs of per-input three-call median client elapsed time to binary PNG consumption.','interval':'10000 paired launch-block bootstrap samples, seed20261029; fixed cases. Pairwise unadjusted95% intervals, observed ranking.','repeatability':'Odd/even block split is a diagnostic warning; no all-participant ratio suppression.','failures':'No outlier trimming. Errors/unsupported/contract failures retained. A correctness/stability failure excludes that input for all participants; any measured timeout changes history and makes the campaign incomplete rather than silently replacing a block.','timingScope':'Warm repeated export. No cold-start, widget frame, source-update or DOM presentation claim. Driver IPC and binary delivery included, file and SVG witness capture after clock.'}
(base/'campaign-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
